'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const refs=['디모데후서 3:16–17','여호수아 1:8','요한복음 16:24','요한계시록 1:8','주기도문','마태복음 16:16','사도신경','로마서 5:8','요한복음 7:37–38','에베소서 2:8','마태복음 22:37–38','마태복음 22:39','요한일서 2:17','고린도전서 15:57–58','에베소서 4:3–4'];
const lessons=[1,2,3,4,4,5,5,6,7,8,9,10,11,12,13];
const uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const initial=()=>({schema:1,theme:'system',goal:3,plans:[{id:'yes',title:'새일꾼반'}],items:refs.map((ref,i)=>({id:'yes-'+i,plan:'yes',lesson:lessons[i],ref,text:'',translation:'개역개정',lang:'ko-KR',favorite:false,notes:'',version:1})),attempts:[],reviews:{},trash:[],audio:{rate:1,repeat:3,gap:5,reference:true,shuffle:false,timer:0},listening:0});
const identity=window.YES_IDENTITY;if(!identity?.id)throw Error('Authentication required');const storageKey='yes-word-v1:'+identity.id;let db;try{db=JSON.parse(localStorage.getItem(storageKey))||initial();if(db.schema!==1||!Array.isArray(db.items)||!Array.isArray(db.plans)||!Array.isArray(db.attempts))throw Error()}catch{db=initial()}db.profile={...identity.profile};
function save(){try{localStorage.setItem(storageKey,JSON.stringify(db));syncSchedule()}catch(e){toast('저장 공간이 부족합니다. 백업해 주세요.')}}
/* v0.6: private, revision-checked cloud snapshots. No audio blobs or auth tokens. */
const syncKey=storageKey+':cloud-meta', conflictKey=storageKey+':cloud-conflict-backup';
let syncMeta={enabled:false,revision:null,digest:null}, syncBusy=false,syncTimer=null,syncMessage='클라우드 백업을 아직 시작하지 않았습니다.';
try{let m=JSON.parse(localStorage.getItem(syncKey));if(m&&typeof m.enabled==='boolean')syncMeta=m}catch{}
function cloudData(){let {schema,theme,goal,plans,items,attempts,reviews,trash,audio,listening}=db;return {schema,theme,goal,plans,items,attempts,reviews,trash,audio,listening}}
function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().filter(k=>x[k]!==undefined).map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x)}
async function digest(x){let bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(x)));return Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('')}
function validSnapshot(x){const safeId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,128}$/.test(v), obj=v=>v&&typeof v==='object'&&!Array.isArray(v), text=v=>typeof v==='string', itemOK=i=>obj(i)&&safeId(i.id)&&safeId(i.plan)&&text(i.ref)&&text(i.text)&&(!i.notes||text(i.notes));return obj(x)&&x.schema===1&&Array.isArray(x.plans)&&x.plans.every(p=>obj(p)&&safeId(p.id)&&text(p.title))&&Array.isArray(x.items)&&x.items.every(itemOK)&&Array.isArray(x.trash)&&x.trash.every(itemOK)&&Array.isArray(x.attempts)&&x.attempts.every(a=>obj(a)&&safeId(a.item)&&Number.isFinite(a.time))&&obj(x.reviews)&&obj(x.audio)&&Number.isFinite(x.goal)&&Number.isFinite(x.listening)&&['light','dark','system'].includes(x.theme)&&new TextEncoder().encode(JSON.stringify(x)).length<=1800000}
function nonempty(x){return x.items.some(i=>i.text.trim()||i.favorite||i.notes)||x.attempts.length||x.plans.length>1||x.trash.length||x.items.length!==refs.length||x.items.some((i,n)=>i.ref!==refs[n])}
function cloudStatus(msg){syncMessage=msg;let e=$('#cloud-status');if(e)e.textContent=msg}
function persistSync(m){localStorage.setItem(syncKey,JSON.stringify(m));syncMeta=m}
function syncSchedule(){if(!syncMeta.enabled||syncBusy||syncMeta.revision===null||!window.YES_CLIENT||!navigator.onLine)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud('auto'),1200)}
function syncPanel(){return '<section class="card stack"><h3>클라우드 동기화</h3><p id="cloud-status" role="status">'+esc(syncMessage)+'</p><small>말씀, 플랜, 묵상 노트, 학습 기록 및 설정을 내 계정에만 저장합니다. 녹음은 이 기기에 남습니다. 처음 동기화하기 전에는 서버로 전송하지 않습니다.</small>'+btn('지금 동기화','cloudsync','primary full')+btn(syncMeta.enabled?'자동 백업 끄기':'자동 백업 켜기','cloudtoggle','outline full')+btn('서버 기록 사용 (충돌 해결)','cloudpull','outline full')+btn('이 기기 기록 사용 (충돌 해결)','cloudpush','outline full')+(localStorage.getItem(conflictKey)?btn('충돌 이전 기록 다운로드','cloudconflictbackup','outline full'):'')+'</section>'}
async function syncCloud(mode='manual'){
 if(syncBusy)return;if(!window.YES_CLIENT||!navigator.onLine){cloudStatus('오프라인입니다. 학습 기록은 기기에 저장됩니다.');return}
 syncBusy=true;clearTimeout(syncTimer);let c=window.YES_CLIENT;cloudStatus('동기화 확인 중…');
 try{
  let local=JSON.parse(JSON.stringify(cloudData()));if(!validSnapshot(local))throw Error('저장 데이터 형식 또는 용량을 확인하세요.');
  let localHash=await digest(local),q=await c.from('learning_snapshots').select('payload,revision,updated_at').eq('user_id',identity.id).maybeSingle();
  if(q.error)throw q.error;let remote=q.data,rev=remote?Number(remote.revision):null;
  if(remote&&(!validSnapshot(remote.payload)||!Number.isSafeInteger(rev)||rev<1))throw Error('서버 기록 형식을 확인할 수 없습니다.');
  let remoteHash=remote?await digest(remote.payload):null;
  let localChanged=syncMeta.digest!==localHash,remoteChanged=syncMeta.revision!==rev;
  let finish=(revision,hash)=>{persistSync({...syncMeta,revision,digest:hash});cloudStatus('동기화 완료 · '+new Date().toLocaleString('ko-KR'))};
  if(remoteHash===localHash){finish(rev,localHash);return}
  if(mode==='auto'&&(remoteChanged||!remote)){cloudStatus('다른 기기에서 변경되었거나 서버 기록이 없습니다. MY에서 지금 동기화해 주세요.');return}
  let pull=mode==='pull'||(mode==='manual'&&remote&&((syncMeta.revision===null&&!nonempty(local))||(!localChanged&&remoteChanged)));
  let push=mode==='push'||(!remote&&mode==='manual')||(!remoteChanged&&localChanged&&syncMeta.revision!==null);
  if(pull){
   if(!remote)throw Error('서버에 저장된 기록이 없습니다.');
   if(page!=='my')throw Error('MY 화면에서 다시 시도하세요.');
   if(!confirm('서버 기록을 이 기기에 적용할까요? 현재 기록은 충돌 백업으로 보존됩니다.')){cloudStatus('동기화 취소');return}
   if(await digest(cloudData())!==localHash||page!=='my')throw Error('현재 기록이 변경되었습니다. 다시 시도하세요.');
   localStorage.setItem(conflictKey,JSON.stringify(local));
   let next={...initial(),...remote.payload,profile:db.profile};localStorage.setItem(storageKey,JSON.stringify(next));db=next;theme();finish(rev,remoteHash);render();return
  }
  if(!push){cloudStatus('두 기기의 기록이 다릅니다. 서버 기록 또는 이 기기 기록을 선택하세요. 자동 덮어쓰기는 하지 않습니다.');return}
  if(mode==='push'&&remote){if(!confirm('이 기기의 기록으로 서버 기록을 교체할까요? 서버의 기존 기록은 이 기기에 별도 백업됩니다.')){cloudStatus('동기화 취소');return}localStorage.setItem(conflictKey,JSON.stringify(remote.payload))}
  if(!remote&&mode==='manual'&&!confirm('이 계정의 말씀 및 학습 기록을 클라우드에 처음 저장할까요?')){cloudStatus('동기화 취소');return}
  if(await digest(cloudData())!==localHash)throw Error('학습 기록이 변경되었습니다. 다시 시도하세요.');
  let write=remote?await c.from('learning_snapshots').update({payload:local,revision:rev+1}).eq('user_id',identity.id).eq('revision',rev).select('revision').maybeSingle():await c.from('learning_snapshots').insert({user_id:identity.id,payload:local,revision:1}).select('revision').single();
  if(write.error)throw write.error;if(!write.data)throw Error('다른 기기에서 변경되었습니다. 다시 동기화하세요.');
  finish(Number(write.data.revision),localHash);
 }catch(e){cloudStatus('동기화 실패 · '+(e.code==='42P01'||e.code==='PGRST205'?'서버 DB 설정이 아직 완료되지 않았습니다.':e.message||'다시 시도하세요.'))}
 finally{syncBusy=false}
}

