const day=(d=Date.now())=>new Date(d).toLocaleDateString('sv-SE'); const filled=()=>db.items.filter(x=>x.text.trim()); const item=id=>db.items.find(x=>x.id===id);const plan=id=>db.plans.find(x=>x.id===id);const due=()=>filled().filter(x=>!db.reviews[x.id]||db.reviews[x.id].next<=Date.now());
const mastery=x=>{let r=db.reviews[x.id];return !x.text.trim()?0:!r?1:r.passes>=3&&r.tested?4:r.tested||r.self?3:2};const complete=x=>mastery(x)>=3;const pct=xs=>xs.length?Math.round(xs.filter(complete).length/xs.length*100):0;
const affiliations=['YES 청년부 · 새일꾼반','YES 청년부','개인 / 기타'];const validProfile=p=>p&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=40&&affiliations.includes(p.affiliation);let page='home',currentPlan='yes',editId=null,session=null,toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
