function bindProfile(){ $('#profileform').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),p={id:db.profile?.id||uid(),name:f.name.trim(),affiliation:f.affiliation,createdAt:db.profile?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(!validProfile(p))return toast('이름과 소속을 확인해 주세요.');if(!window.YES_CLIENT)return toast('온라인 상태에서 프로필을 수정하세요.');let result=await window.YES_CLIENT.from('profiles').update({display_name:p.name,affiliation:p.affiliation}).eq('id',identity.id).select('id').single();if(result.error)return toast('프로필 저장 실패');p.id=identity.id;db.profile=p;try{localStorage.setItem('yes-word-device-profile-v1',JSON.stringify({...identity,profile:p}))}catch{}save();history.replaceState({yesPage:'home'},'');go('home',true);toast('프로필이 저장되었습니다.')} }
