const shuffle=xs=>{let a=[...xs];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};const scoped=s=>s==='wrong'?wrongItems():s==='selected'?filled().filter(x=>selectedStudy.has(x.id)):s==='all'?filled():s==='due'?due():s==='fav'?filled().filter(x=>x.favorite):s.startsWith('item:')?filled().filter(x=>x.id===s.slice(5)):filled().filter(x=>x.plan===s);
const norm=s=>String(s).normalize('NFC').toLowerCase().replace(/[\p{P}\p{Z}\s]/gu,'');function score(a,b){a=Array.from(norm(a));b=Array.from(norm(b));let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let cur=[i];for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=cur}return Math.round(100*(1-prev[b.length]/Math.max(a.length,b.length,1)))}
function start(xs,mode='flash',difficulty='medium',random=false){if(!xs.length)return toast('먼저 말씀 본문을 입력해 주세요.');session={ids:(random?shuffle(xs):xs).map(x=>x.id),mode,difficulty,index:0,results:[],q:null};go('session')}
function question(x){let mode=session.mode==='mixed'?shuffle(['blank','order','type','hint'])[0]:session.mode;let tokens=x.text.trim().split(/\s+/);let ratio={easy:.2,medium:.4,hard:.7,expert:1}[session.difficulty];if(session.difficulty==='expert'&&['blank','choice'].includes(mode))mode='type';let hidden=shuffle(tokens.map((_,i)=>i)).slice(0,Math.max(1,Math.round(tokens.length*ratio)));let q={mode,tokens,hidden,flip:false,selected:[],answers:{},typed:'',hint:false,graded:false,score:0,order:shuffle(tokens.map((_,i)=>i))};q.choices={};for(let i of hidden){let other=[...new Set([...tokens,...filled().flatMap(v=>v.text.split(/\s+/))])].filter(t=>norm(t)&&norm(t)!==norm(tokens[i]));let seen=new Set();other=other.filter(t=>!seen.has(norm(t))&&seen.add(norm(t)));q.choices[i]=shuffle([tokens[i],...shuffle(other).slice(0,3)])}return q}
function studySession(){if(!session||session.index>=session.ids.length)return go('result');let x=item(session.ids[session.index]);if(!x)return nextQuestion();let q=session.q||(session.q=question(x));let flash=['flash','reverse'].includes(q.mode);let body='';if(flash){let front=q.mode==='flash'?x.ref:x.text,back=q.mode==='flash'?x.text:x.ref;body=`<button class="flip" data-act="flip"><small>${q.flip?'정답':'말씀을 떠올려 보세요'}</small><span class="verse">${esc(q.flip?back:front)}</span><small>탭하여 뒤집기 ↻</small></button>${q.flip?`<div class="grid">${btn('다시 연습','rate:again','outline')}${btn('어려워요','rate:hard','outline')}${btn('외웠어요','rate:good','primary')}${btn('완벽해요','rate:easy','primary')}</div>`:''}`}else if(q.mode==='order'){body=`<div class="card tokens" id="answerOrder">${q.selected.length?q.selected.map(i=>btn(esc(q.tokens[i]),'unpick:'+i,'outline',q.graded?'disabled':'')).join(''):'<small>아래 단어를 순서대로 선택하세요.</small>'}</div><div class="tokens">${q.order.filter(i=>!q.selected.includes(i)).map(i=>btn(esc(q.tokens[i]),'pick:'+i,'',q.graded?'disabled':'')).join('')}</div>`}else if(['blank','choice'].includes(q.mode)){body=`<div class="card verse">${q.tokens.map((t,i)=>!q.hidden.includes(i)?esc(t):q.mode==='choice'&&q.choices[i].length>1?`<select class="blank" data-answer="${i}" ${q.graded?'disabled':''}>${options([['','선택'],...q.choices[i].map(a=>[a,a])],q.answers[i]||'')}</select>`:`<input class="blank" data-answer="${i}" value="${esc(q.answers[i]||'')}" placeholder="${q.hint?esc(wordHint(t)):'___'}" ${q.graded?'disabled':''}>`).join(' ')}</div>`}else{body=(q.mode==='hint'?`<div class="card verse">${esc(q.tokens.map(wordHint).join(' '))}</div>`:'')+`<textarea id="recall" rows="7" placeholder="말씀을 기억하며 입력하세요" ${q.graded?'disabled':''}>${esc(q.typed)}</textarea>`}if(!flash){body+=q.graded?`<section class="card"><div class="metric ${q.score>=90?'good':'error'}">${q.score}점</div><small>${q.hint?'힌트 사용 · 암송 성공 판정 제외':''}</small><h3>원문</h3><p class="verse">${esc(x.text)}</p></section>${btn('다음 →','next','primary full')}`:`<div class="row">${btn('힌트 보기','hintshow','outline grow')}${btn('채점하기','grade','primary grow')}</div>${q.hint?`<div class="hint-panel"><small>초성 힌트</small><p>${esc(q.tokens.map((t,i)=>['blank','choice'].includes(q.mode)&&!q.hidden.includes(i)?t:wordHint(t)).join(' '))}</p></div>`:''}`}app.innerHTML=`<div class="row between">${btn('종료','endstudy','outline')}<small>${session.index+1} / ${session.ids.length}</small></div>${bar(session.index/session.ids.length*100)}<h2>${esc(q.mode==='reverse'?'성경 주소를 떠올려 보세요':x.ref)}</h2><p class="muted">${modes.find(m=>m[0]===q.mode)?.[1]}</p>${body}`;app.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>q.answers[el.dataset.answer]=el.value);if($('#recall'))$('#recall').oninput=e=>q.typed=e.target.value}
function logAttempt(x,sc,rating,kind,hint){let now=Date.now(),r=db.reviews[x.id]||{stage:-1,passes:0,tested:false,self:false,lastPass:0,next:0};let wasDue=r.next<=now;let pass=rating==='good'||rating==='easy';if(pass){r.stage=Math.min(4,r.stage+1);if(kind==='test'&&!hint&&sc>=90){if(r.tested&&wasDue&&day(r.lastPass)!==day(now))r.passes++;r.tested=true;r.lastPass=now}else if(kind==='self')r.self=true}else if(rating==='again'){r.stage=-1;r.passes=0;r.tested=false;r.self=false}r.next=now+86400000*[1,3,7,14,30][Math.max(0,r.stage)];db.reviews[x.id]=r;let a={id:uid(),item:x.id,time:now,mode:session?.q?.mode||'voice',score:sc,rating,kind,hint,version:x.version};db.attempts.push(a);session?.results.push(a);save()}
function grade(){let q=session.q,x=item(session.ids[session.index]);if(q.graded)return;let sc;if(q.mode==='order')sc=score(q.selected.map(i=>q.tokens[i]).join(' '),x.text);else if(['blank','choice'].includes(q.mode))sc=Math.round(q.hidden.filter(i=>norm(q.answers[i]||'')===norm(q.tokens[i])).length/q.hidden.length*100);else sc=score(q.typed,x.text);q.score=sc;q.graded=true;let full=['type','order'].includes(q.mode)||(['blank','choice'].includes(q.mode)&&q.hidden.length===q.tokens.length);let kind=full?'test':'practice';logAttempt(x,sc,sc>=90&&!q.hint?'good':sc>=60?'hard':'again',kind,q.hint);render()}
