function stopAllPlayback(){communityStop();stopAudio();document.querySelectorAll('audio').forEach(a=>{a.pause();a.currentTime=0});recUrls.forEach(URL.revokeObjectURL);recUrls=[]}function stopAudio(){audioRun++;window.speechSynthesis?.cancel();clearTimeout(audioTimer);audioState.active=false;audioState.paused=false;audioUI()}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));function speak(text,lang,run){return new Promise(resolve=>{if(run!==audioRun)return resolve(false);let u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=db.audio.rate;let v=voices().find(v=>v.voiceURI===db.audio.voice&&v.lang.startsWith(lang.slice(0,2)))||voices().find(v=>v.lang===lang);if(v)u.voice=v;let started=Date.now();u.onend=()=>{if(run===audioRun){db.listening+=Math.max(0,Math.round((Date.now()-started)/1000));save()}resolve(true)};u.onerror=()=>resolve(false);speechSynthesis.speak(u)})}
async function playAudio(scope){if(!('speechSynthesis'in window))return toast('이 브라우저는 자동 읽기를 지원하지 않습니다.');let xs=scoped(scope);if(!xs.length)return toast('먼저 말씀을 입력해 주세요.');stopAudio();let run=audioRun;audioState={active:true,ref:xs[0].ref,index:0,total:xs.length,scope,paused:false};if(db.audio.shuffle)xs=shuffle(xs);if(db.audio.timer)audioTimer=setTimeout(stopAudio,db.audio.timer*60000);for(let i=0;i<xs.length&&run===audioRun;i++){let x=xs[i];audioState.ref=x.ref;audioState.index=i;audioUI();let n=db.audio.repeat||Infinity;for(let j=0;j<n&&run===audioRun;j++){while(audioState.paused&&run===audioRun)await sleep(200);if(run!==audioRun)return;let ok=await speak((db.audio.reference?x.ref+'. ':'')+x.text,x.lang,run);if(!ok){if(run===audioRun){stopAudio();toast('음성 재생이 중단되었습니다.')}return}if(j<n-1||i<xs.length-1)await sleep(db.audio.gap*1000)}}if(run===audioRun)stopAudio()}
let recDB;function audioDB(){return recDB||(recDB=new Promise((resolve,reject)=>{let req=indexedDB.open('yes-word-recordings:'+identity.id,1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}))}async function recOp(mode,fn){let d=await audioDB();return new Promise((resolve,reject)=>{let tx=d.transaction('recordings',mode),r=fn(tx.objectStore('recordings'));tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
let recording=null,recStream=null,recStart=0,recInterval=null,recPending=false,recUrls=[];async function record(){stopAllPlayback();recUrls.forEach(URL.revokeObjectURL);recUrls=[];app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Recite','내 목소리로 암송')+`<section class="card center"><label>암송할 말씀</label><select id="recItem">${options(filled().map(x=>[x.id,x.ref]),filled()[0]?.id)}</select><p class="muted">본문을 보지 않고 암송해 보세요.</p><div class="metric" id="recTime">00:00</div><div class="row" style="justify-content:center;margin:16px 0">${btn('● 녹음 시작','recstart','primary')}${btn('■ 종료','recstop','outline','disabled')}</div><p class="muted">최대 5분 · 이 기기에만 저장</p>${btn('원문 듣기','reccompare','outline full')}</section><h2>녹음 기록</h2><div id="recList">불러오는 중…</div>`;try{let rows=await recOp('readonly',s=>s.getAll());if(page!=='record'||!$('#recList'))return;$('#recList').innerHTML=rows.length?rows.sort((a,b)=>b.time-a.time).map(r=>{let url=URL.createObjectURL(r.blob);recUrls.push(url);return `<section class="card"><h3>${esc(r.name)}</h3><small>${esc(new Date(r.time).toLocaleString('ko-KR'))} · ${Math.round(r.duration/1000)}초</small><div class="record-play"><audio preload="metadata" src="${url}"></audio><button class="outline" data-act="recordplay:${r.id}" aria-label="녹음 재생 또는 일시정지">▶ 듣기</button><span class="record-time">0:00</span></div><div class="row">${btn('이름 수정','recrename:'+r.id,'outline grow')}${btn('다운로드','recdownload:'+r.id,'outline')}${btn('삭제','recdelete:'+r.id,'outline')}</div></section>`}).join(''):'<p class="muted">아직 녹음이 없습니다.</p>'}catch{if($('#recList'))$('#recList').textContent='녹음 저장소에 접근할 수 없습니다.'}}
async function recStartFn(){if(recording||recPending)return;let x=item($('#recItem')?.value);if(!x)return toast('먼저 본문을 입력하세요.');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('HTTPS 환경의 지원 브라우저에서 녹음할 수 있습니다.');recPending=true;try{stopAudio();recStream=await navigator.mediaDevices.getUserMedia({audio:true});if(page!=='record'){recStream.getTracks().forEach(t=>t.stop());return}let chunks=[],r=new MediaRecorder(recStream);recording=r;recStart=Date.now();r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=async()=>{clearInterval(recInterval);recStream?.getTracks().forEach(t=>t.stop());recording=null;let blob=new Blob(chunks,{type:r.mimeType||chunks[0]?.type||'audio/webm'});try{await recOp('readwrite',s=>s.put({id:uid(),item:x.id,name:x.ref,blob,time:Date.now(),duration:Date.now()-recStart}));toast('녹음 저장 완료')}catch{toast('녹음 저장에 실패했습니다.')}if(page==='record')record()};r.onerror=()=>{recStream?.getTracks().forEach(t=>t.stop());clearInterval(recInterval);recording=null;toast('녹음 오류');if(page==='record')record()};r.start();$('[data-act=recstart]').disabled=true;$('[data-act=recstop]').disabled=false;recInterval=setInterval(()=>{let sec=Math.floor((Date.now()-recStart)/1000);if($('#recTime'))$('#recTime').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec>=300&&r.state==='recording')r.stop()},250)}catch{recStream?.getTracks().forEach(t=>t.stop());recording=null;toast('마이크 권한 또는 기기를 확인하세요.')}finally{recPending=false}}
function streak(){let days=new Set(db.attempts.map(a=>day(a.time)));let d=new Date(),n=0;if(!days.has(day(d)))d.setDate(d.getDate()-1);while(days.has(day(d))){n++;d.setDate(d.getDate()-1)}return n}
function my(){adminCheck().then(()=>{if(page==='my'&&$('#community-links'))$('#community-links').innerHTML=communityNav()});let count=filled().filter(complete).length,st=streak(),scores=db.attempts.filter(a=>a.score!==null);db.trash=db.trash.filter(x=>Date.now()-x.deleted<172800000);save();app.innerHTML=heading('My journey','나의 기록')+`<section class="card row between account-overview"><div><h3>${esc(db.profile.name)}</h3><small>${esc(db.profile.affiliation)}</small></div>${btn('프로필','goto:profile','outline')}</section><section class="card stack" id="community-links">${communityNav()}</section><div class="grid"><div class="card"><small>연속 학습</small><div class="metric">${st}일</div></div><div class="card"><small>암송 완료</small><div class="metric">${count}개</div></div><div class="card"><small>전체 학습</small><div class="metric">${db.attempts.length}회</div></div><div class="card"><small>말씀 듣기</small><div class="metric">${Math.floor(db.listening/60)}분</div></div></div>${historySummary()}<section class="card stack"><h3>설정</h3><p class="muted">${esc(identity.email||'')}</p>${btn('로그아웃','signout','outline')}${btn('이전 기기 기록 가져오기','legacyimport','outline')}${btn("나의 프로필 수정","goto:profile","outline")}${btn("앱 설치 및 오프라인 안내","goto:install","outline")}<label>하루 학습 목표</label><input type="number" min="1" max="100" id="goal" value="${db.goal}"><label>테마</label><select id="themeselect">${options([['system','시스템'],['light','라이트'],['dark','다크']],db.theme)}</select>${btn('즐겨찾기 암송','favoriteStudy','outline')}${btn('개인 데이터 JSON 백업','backup','outline')}${btn('백업 복원','restore','outline')}<input type="file" id="restorefile" accept="application/json" hidden><small>녹음 파일은 별도로 다운로드하세요. 데이터는 이 기기의 브라우저에 저장됩니다. 로그인은 연결되었습니다. 학습 기록은 계정별로 이 기기에 저장됩니다. 아래 클라우드 동기화에서 선택적으로 백업할 수 있습니다.</small></section>${syncPanel()}<h2>휴지통</h2>${db.trash.map(x=>`<div class="card row between"><span>${esc(x.ref)}</span>${btn('복구','recover:'+x.id,'outline')}</div>`).join('')||'<p class="muted">삭제된 항목이 없습니다.</p>'}<p class="muted">YES WORD v0.16 · 학습 기록 베타</p>`;$('#goal').onchange=e=>{db.goal=Math.max(1,Math.min(100,Number(e.target.value)||3));save()};$('#themeselect').onchange=e=>{db.theme=e.target.value;save();theme()};$('#restorefile').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let o=JSON.parse(await f.text());if(o.schema!==1||!Array.isArray(o.items)||!Array.isArray(o.plans)||!Array.isArray(o.attempts)||!o.reviews||!o.audio||!Array.isArray(o.trash)||!o.items.every(x=>typeof x.id==='string'&&typeof x.ref==='string'&&typeof x.text==='string'&&typeof x.plan==='string')||!o.plans.every(p=>typeof p.id==='string'&&typeof p.title==='string'))throw Error();if(confirm('현재 개인 학습 데이터를 백업 파일로 교체할까요?')){db={...initial(),...o,profile:db.profile};save();theme();render();toast('복원 완료')}}catch{toast('유효한 YES WORD 백업 파일이 아닙니다.')}}}
function install(){app.innerHTML=btn('← 나의 기록','goto:my','outline')+heading('Install','앱 설치 및 오프라인')+'<section class="card"><h3>iPhone / iPad</h3><p>Safari에서 YES WORD 주소 열기 → 공유 → 홈 화면에 추가 → 추가.</p><h3>Android</h3><p>Chrome 메뉴 ⋮ → 앱 설치 또는 홈 화면에 추가.</p></section><section class="card"><h3>오프라인 사용</h3><p>온라인 상태에서 앱을 한 번 열고 캐시 준비를 확인한 후 비행기 모드에서 다시 실행하세요. 말씀 입력, 암송, 로컬 녹음은 기기에 저장됩니다. 자동 읽기 음성은 기기별로 인터넷이 필요할 수 있습니다.</p><p id="offline-status">확인 중…</p></section>';let el=$('#offline-status');if(!navigator.serviceWorker){el.textContent='이 브라우저는 오프라인 설치를 지원하지 않습니다.';return}navigator.serviceWorker.getRegistration().then(async r=>{let c=await caches.open('yes-word-v16');let checks=await Promise.all(['./','./index.html','./style.css?v=16','./app.js?v=16','./gate.js?v=16','./manifest.webmanifest?v=16','./icon-192.png?v=3','./icon-512.png?v=3'].map(x=>c.match(new URL(x,location.href).href)));if(el.isConnected)el.textContent=r?.active&&checks.every(Boolean)?'오프라인 캐시 준비 완료 · 비행기 모드에서 확인하세요.':'아직 캐시 준비 중입니다. 온라인 상태에서 새로고침해 주세요.'}).catch(()=>{if(el.isConnected)el.textContent='오프라인 상태를 확인할 수 없습니다.'})}
function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function action(a){let [k,id]=a.split(':');if(k.startsWith('official')&&k!=='officialsetting')return officialAction(k,id);if(k.startsWith('cm'))return communityAction(k,id);switch(k){case'historyrange':historyRange=id;historyLimit=30;return historyPage();case'historymore':historyLimit+=30;return historyPage();case'officialsetting':return toggleOfficialSetting();case'favfilter':favFilter=id;return favoritesPage();case'favtrain':if(!scoped('fav').length)return toast('본문이 등록된 말씀을 즐겨찾기에 추가하세요.');studyScope='fav';return go('study');case'cloudsync':return syncCloud();case'cloudpull':return syncCloud('pull');case'cloudpush':return syncCloud('push');case'cloudtoggle':{if(!syncMeta.enabled&&syncMeta.revision===null)return toast('먼저 지금 동기화로 초기 백업을 완료하세요.');persistSync({...syncMeta,enabled:!syncMeta.enabled});syncMessage=syncMeta.enabled?'자동 백업이 켜졌습니다.':'자동 백업이 꺼졌습니다.';if(!syncMeta.enabled)clearTimeout(syncTimer);render();return}case'cloudconflictbackup':return download(new Blob([localStorage.getItem(conflictKey)],{type:'application/json'}),'yes-word-conflict-backup.json');case'signout':{if(syncBusy)return toast('동기화 완료 후 로그아웃하세요.');clearTimeout(syncTimer);if(recording||recPending)return toast('녹음을 먼저 종료하세요.');stopAllPlayback();if(window.YES_CLIENT){let r=await window.YES_CLIENT.auth.signOut({scope:'local'});if(r.error)return toast('로그아웃 실패. 다시 시도하세요.')}localStorage.removeItem('yes-word-auth-v1');localStorage.removeItem('yes-word-device-profile-v1');location.replace('./account.html?v=13');return}case'legacyimport':{if(localStorage.getItem('yes-word-legacy-claimed'))return toast('이전 기록은 이미 다른 계정 또는 현재 계정에 이전되었습니다.');let raw=localStorage.getItem('yes-word-v1');if(!raw)return toast('이전 기록이 없습니다.');let old;try{old=JSON.parse(raw);if(old.schema!==1||!Array.isArray(old.items)||!Array.isArray(old.plans)||!Array.isArray(old.attempts))throw Error()}catch{return toast('이전 데이터 형식을 확인하세요.')}if(db.attempts.length||db.items.some(x=>x.text.trim())||db.plans.length>1)return toast('현재 계정에 학습 데이터가 있습니다. 덮어쓰기를 방지하기 위해 이전할 수 없습니다.');if(!confirm('이 기기의 이전 기록 '+old.items.filter(x=>x.text?.trim()).length+'개와 학습 내역 '+old.attempts.length+'건이 본인의 것인지 확인하세요. 현재 계정에 복사할까요?'))return;let p=db.profile;let next={...initial(),...old,profile:p};try{localStorage.setItem(storageKey,JSON.stringify(next));localStorage.setItem('yes-word-legacy-claimed',identity.id)}catch{return toast('기록 이전 저장 실패')}db=next;save();theme();render();toast('기존 말씀 및 학습 기록 복사 완료. 녹음은 별도 보존됩니다.');return}case'goto':return go(id);case'openplan':currentPlan=id;return go('detail');case'newplan':{let t=$('#planname').value.trim();if(!t)return toast('플랜 이름을 입력하세요.');db.plans.push({id:uid(),title:t});save();return render()}case'renameplan':{let p=plan(id),t=prompt('플랜 이름',p.title);if(t?.trim()){p.title=t.trim();save();render()}return}case'edit':editId=id;return go('edit');case'newitem':editId=null;return go('edit');case'bulk':return startBulk();case'bulkadd':captureBulk();bulkDraft.push({ref:'',text:'',lang:'ko-KR',translation:'개역개정'});return bulkPage();case'bulkremove':captureBulk();bulkDraft.splice(Number(id),1);return bulkPage();case'bulkparse':return parseBulk();case'bulkpreview':return previewBulk();case'bulkback':return bulkPage();case'bulkcommit':return commitBulk();case'trash':if(confirm('이 항목을 삭제할까요? 48시간 동안 복구할 수 있습니다.')){let x=item(id);db.trash.push({...x,deleted:Date.now()});db.items=db.items.filter(y=>y.id!==id);save();go('detail')}return;case'recover':{let x=db.trash.find(y=>y.id===id);if(x){delete x.deleted;db.items.push(x);db.trash=db.trash.filter(y=>y.id!==id);save();render()}return}case'fav':item(id).favorite=!item(id).favorite;save();return render();case'startplan':return start(scoped(id));case'startitem':return start(scoped('item:'+id));case'review':return start(due());case'favoriteStudy':return start(scoped('fav'));case'mode':{let xs=scoped($('#scope').value);if(!xs.length)return toast($('#scope').value==='fav'?'별표를 눌러 본문이 등록된 말씀을 즐겨찾기에 추가하세요.':'학습 범위에 본문이 등록된 말씀이 없습니다.');return start(xs,id,$('#difficulty').value,$('#shuffle').checked)}case'flip':session.q.flip=!session.q.flip;return render();case'rate':{let x=item(session.ids[session.index]);logAttempt(x,null,id,'self',false);return nextQuestion()}case'pick':session.q.selected.push(Number(id));return render();case'unpick':session.q.selected=session.q.selected.filter(i=>i!==Number(id));return render();case'hintshow':session.q.hint=true;return render();case'grade':return grade();case'next':return nextQuestion();case'endstudy':if(confirm('학습을 종료할까요? 완료한 기록은 저장됩니다.'))go('result');return;case'listenplan':audioState.scope=id;go('listen');return playAudio(id);case'play':return playAudio($('#audioScope').value);case'pause':if(audioState.active){audioState.paused=!audioState.paused;if(audioState.paused)speechSynthesis.pause();else speechSynthesis.resume();audioUI()}return;case'stop':return stopAudio();case'recordplay':{let b=document.querySelector(`[data-act="recordplay:${id}"]`),a=b?.parentElement.querySelector('audio');if(!a)return;if(a.paused){await a.play();b.textContent='Ⅱ 일시정지'}else{a.pause();b.textContent='▶ 듣기'}a.ontimeupdate=()=>{let t=Math.floor(a.currentTime);b.parentElement.querySelector('.record-time').textContent=Math.floor(t/60)+':'+String(t%60).padStart(2,'0')};a.onpause=()=>b.textContent='▶ 듣기';a.onended=()=>b.textContent='▶ 듣기';return}case'recstart':return recStartFn();case'recstop':if(recording?.state==='recording')recording.stop();return;case'reccompare':if(recording)return toast('녹음을 먼저 종료하세요.');return playAudio('item:'+$('#recItem').value);case'recdelete':if(confirm('녹음을 삭제할까요?')){await recOp('readwrite',s=>s.delete(id));record()}return;case'recrename':{let r=await recOp('readonly',s=>s.get(id)),name=prompt('녹음 이름',r.name);if(name?.trim()){r.name=name.trim();await recOp('readwrite',s=>s.put(r));record()}return}case'recdownload':{let r=await recOp('readonly',s=>s.get(id));download(r.blob,r.name+'.'+(r.blob.type.includes('mp4')?'m4a':r.blob.type.includes('ogg')?'ogg':'webm'));return}case'backup':return download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'yes-word-'+day()+'.json');case'restore':return $('#restorefile').click()}}
'use strict';
// Community UI runs inside the authenticated app, uses only RLS/RPC protected endpoints.
const communityClient=()=>window.YES_CLIENT;
let communityAdmin=false,communityGroups=[],communityPlayer=null,communityEpoch=0,communityRecorder=null,communityStream=null;
const englishRefs=['2 Timothy 3:16–17','Joshua 1:8','John 16:24','Revelation 1:8',"The Lord's Prayer",'Matthew 16:16',"Apostles' Creed",'Romans 5:8','John 7:37–38','Ephesians 2:8','Matthew 22:37–38','Matthew 22:39','1 John 2:17','1 Corinthians 15:57–58','Ephesians 4:3–4'];
function communityStop(){communityEpoch++;officialClean();if(communityPlayer){communityPlayer.pause();communityPlayer.removeAttribute('src');communityPlayer=null}if(communityRecorder&&communityRecorder.state==='recording')communityRecorder.stop();communityStream?.getTracks().forEach(t=>t.stop());communityStream=null}
function must(r){if(r.error)throw r.error;return r.data}
function onlineCommunity(){if(!communityClient()||!navigator.onLine)throw Error('온라인에서 로그인한 후 사용하세요.');return communityClient()}
async function adminCheck(){try{communityAdmin=must(await onlineCommunity().rpc('yw_is_admin'))===true}catch{communityAdmin=false}await refreshOfficialSetting();return communityAdmin}
function communityNav(){return (communityAdmin?btn('관리자 대시보드','goto:admin','primary full'):'')+btn('YES 공동체','goto:community','outline full')+(officialEnabled?btn('공식 말씀 음성','goto:official','outline full'):'')}
function communityError(e){toast(e?.message||'처리하지 못했습니다.');}
function safeUuid(v){return typeof v==='string'&&/^[a-f0-9-]{36}$/i.test(v)}
function field(id){return document.getElementById(id)?.value||''}
function cmButton(label,act,cls='outline'){return btn(label,act,cls)}
function cmDate(v){return v?new Date(v).toLocaleString('ko-KR'):'—'}
async function adminPage(){let epoch=++communityEpoch;app.innerHTML=heading('Administration','관리자')+'<p>권한 확인 중…</p>';try{if(!await adminCheck())throw Error('관리자만 접근할 수 있습니다.');let c=onlineCommunity(),[users,groups,curriculum,audios]=await Promise.all([c.rpc('yw_admin_users'),c.from('yw_groups').select('*').order('created_at',{ascending:false}),c.from('official_curriculum').select('*').order('lesson'),c.from('official_audio').select('*').order('created_at',{ascending:false})]).then(rs=>rs.map(must));if(page!=='admin'||epoch!==communityEpoch)return;let recent=users.filter(u=>u.last_login&&day(new Date(u.last_login))===day()).length;app.innerHTML=btn('← MY','goto:my','outline')+heading('Administration','YES WORD 관리자')+'<div class="grid"><section class="card"><small>가입 계정</small><div class="metric">'+users.length+'</div></section><section class="card"><small>오늘 로그인</small><div class="metric">'+recent+'</div></section></div><h2>가입 사용자</h2>'+users.map(u=>'<section class="card"><b>'+esc(u.display_name||'프로필 미등록')+'</b><p>'+esc(u.email)+'</p><small>'+esc(u.affiliation||'')+' · 가입 '+esc(cmDate(u.joined_at))+' · 마지막 백업 '+esc(cmDate(u.backup_at))+'</small></section>').join('')+'<h2>그룹 관리</h2><section class="card stack"><input id="new-group" placeholder="2027 상반기 새일꾼반"><button data-act="cmcreate" class="primary">그룹 생성</button></section>'+groups.map(g=>'<section class="card"><h3>'+esc(g.name)+'</h3><small>'+(g.active?'운영 중':'종료')+'</small><div class="stack">'+btn('명단 및 리더 설정','cmroster:'+g.id,'outline')+btn('7일 초대 코드 생성','cminvite:'+g.id,'outline')+btn(g.active?'그룹 종료':'그룹 재개','cmtoggle:'+g.id,'outline')+'</div></section>').join('')+'<h2>암송 과정 관리</h2><p class="muted">공식 주소 15개는 유지하고 과별 제목을 편집합니다. 본문은 각 사용자가 입력합니다.</p>'+curriculum.map(x=>'<section class="card"><small>'+x.lesson+'과</small><b>'+esc(x.reference_ko)+'</b><p>'+esc(x.reference_en)+'</p><p>'+esc(x.lesson_title)+'</p>'+btn('과 제목 편집','cmtitle:'+x.item_key,'outline')+'</section>').join('')+'<h2>공식 음성 관리</h2>"+serviceSettingsPanel()+"<h2>공식 음성 등록</h2><section class="card stack"><label>암송 항목</label><select id="official-item">'+options(curriculum.map(x=>[x.item_key,x.reference_ko]),curriculum[0]?.item_key)+'</select><label>언어</label><select id="official-lang"><option value="ko-KR">한국어</option><option value="en-US">English</option></select><label>음성 제목</label><input id="official-title" maxlength="120" placeholder="공식 암송 음성"><label>사용 허가를 받은 음성만 업로드하세요.</label><input type="file" id="official-file" accept="audio/*,video/webm"><button class="primary" data-act="cmupload">파일 등록 (비공개 초안)</button><button class="outline" data-act="cmrecord">직접 녹음 시작</button><button class="outline" data-act="cmrecordstop">녹음 종료 및 초안 저장</button></section>'+audios.map(a=>'<section class="card"><b>'+esc(a.title)+'</b><p>'+esc(a.item_key)+' · '+esc(a.language)+' · '+(a.published?'공개':'초안')+'</p>'+btn('미리 듣기','cmplay:'+a.id,'outline')+btn(a.published?'비공개 전환':'공개하기','cmpublish:'+a.id,'outline')+btn('삭제','cmdeleteaudio:'+a.id,'outline')+'</section>').join('');}catch(e){if(page==='admin'&&epoch===communityEpoch)app.innerHTML=heading('Administration','관리자')+'<section class="card">'+esc(e.message)+'<p>'+btn('돌아가기','goto:my','outline')+'</p></section>'}}
async function communityPage(){let epoch=++communityEpoch;app.innerHTML=heading('Community','YES 공동체')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),[groups,members]=await Promise.all([c.from('yw_groups').select('*'),c.from('yw_members').select('group_id,role').eq('user_id',identity.id)]).then(rs=>rs.map(must));if(page!=='community'||epoch!==communityEpoch)return;communityGroups=groups.filter(g=>members.some(m=>m.group_id===g.id));app.innerHTML=btn('← MY','goto:my','outline')+heading('Community','YES 공동체')+'<section class="card stack"><h3>그룹 참여</h3><input id="group-code" placeholder="리더에게 받은 초대 코드"><button class="primary" data-act="cmjoin">가입하기</button></section>'+communityGroups.map(g=>'<section class="card"><h3>'+esc(g.name)+'</h3><small>'+esc(members.find(m=>m.group_id===g.id)?.role==='leader'?'담당 리더':'학생')+'</small><p>새일꾼반 15개 기본 항목의 요약 진척도만 공유합니다.</p>'+btn('내 진척도 제출','cmprogress:'+g.id,'primary full')+btn('그룹 녹음 및 피드백','cmsubmissions:'+g.id,'outline full')+(members.find(m=>m.group_id===g.id)?.role==='leader'?btn('학생 진척도 보기','cmroster:'+g.id,'outline full'):'')+'</section>').join('')+(communityGroups.length?'':'<p class="muted">가입한 그룹이 없습니다.</p>');}catch(e){if(page==='community'&&epoch===communityEpoch)app.innerHTML=heading('Community','YES 공동체')+'<section class="card">'+esc(e.message)+'</section>'}}
let officialRows=[],officialUrl=null,officialCancel=null,officialPaused=false,officialActive=false;
const officialDB=()=>new Promise((ok,no)=>{let q=indexedDB.open('yw-official-cache:'+identity.id,1);q.onupgradeneeded=()=>q.result.createObjectStore('audio',{keyPath:'id'});q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)});
async function officialOp(mode,fn){let d=await officialDB();try{return await new Promise((ok,no)=>{let tx=d.transaction('audio',mode),q=fn(tx.objectStore('audio'));tx.oncomplete=()=>ok(q.result);tx.onerror=()=>no(tx.error);tx.onabort=()=>no(tx.error)})}finally{d.close()}}
function officialStatus(t){let e=$('#official-status');if(e)e.textContent=t}
function officialClean(){officialActive=false;officialPaused=false;if(officialCancel){let f=officialCancel;officialCancel=null;f(false)}if(officialUrl){URL.revokeObjectURL(officialUrl);officialUrl=null}}
async function officialPage(){let epoch=++communityEpoch;await refreshOfficialSetting();if(page!=='official'||epoch!==communityEpoch)return;if(!officialEnabled){app.innerHTML=heading('Audio','공식 말씀 음성')+'<section class="card">공식 음성 서비스가 현재 제공되지 않습니다.</section>'+btn('← 말씀 듣기','goto:listen','outline full');return;}app.innerHTML=heading('Audio','공식 말씀 음성')+'<p>불러오는 중…</p>';try{let saved=await officialOp('readonly',s=>s.getAll()).catch(()=>[]),online=!!window.YES_CLIENT&&navigator.onLine;let rows;if(online){let c=onlineCommunity();rows=must(await c.from('official_audio').select('id,item_key,language,title,object_path,created_at').eq('published',true).order('created_at'));let live=new Set(rows.map(a=>a.id));for(let a of saved.filter(x=>!live.has(x.id)))await officialOp('readwrite',s=>s.delete(a.id));saved=saved.filter(x=>live.has(x.id))}else rows=saved.map(x=>x.meta);if(page!=='official'||epoch!==communityEpoch)return;officialRows=rows.sort((a,b)=>Number(a.item_key.slice(4))-Number(b.item_key.slice(4))||a.language.localeCompare(b.language));let ids=new Set(saved.map(x=>x.id));app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Audio','공식 말씀 음성')+'<p class="muted">'+(online?'관리자가 공개한 암송 음성입니다. 다운로드한 음성은 오프라인에서도 들을 수 있습니다.':'오프라인 · 이 계정에 다운로드한 음성만 표시합니다.')+'</p><section class="card stack"><h3>암송 플레이어</h3><p id="official-status" role="status">재생 대기</p><div class="grid"><div><label>반복 횟수</label><select id="official-repeat">'+options([1,3,5,10].map(n=>[n,n+'회']),3)+'</select></div><div><label>속도</label><select id="official-speed">'+options([.75,.9,1,1.15,1.25].map(n=>[n,n+'×']),1)+'</select></div><div><label>반복 사이 휴식</label><select id="official-gap">'+options([0,3,5,10].map(n=>[n,n+'초']),3)+'</select></div><div><label>언어</label><select id="official-language">'+options([['all','전체'],['ko-KR','한국어'],['en-US','English']],'ko-KR')+'</select></div></div>'+btn('순서대로 연속 듣기','officialqueue','primary full')+'<div class="row">'+btn('일시정지 / 계속','officialpause','outline grow')+btn('정지','officialstop','outline')+'</div></section>'+officialRows.map(a=>'<section class="card"><b>'+esc(a.title)+'</b><p>'+esc(a.language==='en-US'?englishRefs[Number(a.item_key.slice(4))]:refs[Number(a.item_key.slice(4))])+' · '+(a.language==='en-US'?'영어':'한국어')+'</p><small>'+(ids.has(a.id)?'오프라인 저장 완료':'온라인 음성')+'</small><div class="row">'+btn('재생','officialsingle:'+a.id,'primary grow')+(ids.has(a.id)?btn('기기 저장 삭제','officialremove:'+a.id,'outline'):online?btn('오프라인 저장','officialdownload:'+a.id,'outline'):'')+'</div></section>').join('')+(rows.length?'':'<section class="card">등록된 음성이 없습니다.</section>')}catch(e){if(page==='official'&&epoch===communityEpoch)app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Audio','공식 말씀 음성')+'<section class="card">'+esc(e.message||'음성 목록을 불러오지 못했습니다.')+'</section>'}}
async function officialBlob(a){let cached=await officialOp('readonly',s=>s.get(a.id)).catch(()=>null);if(cached?.blob&&cached.meta?.object_path===a.object_path)return cached.blob;return must(await onlineCommunity().storage.from('yw-official-audio').download(a.object_path))}
async function officialPlay(rows){if(!rows.length)return toast('재생할 음성이 없습니다.');let repeat=Math.max(1,Math.min(10,Number(field('official-repeat'))||1)),speed=Number(field('official-speed'))||1,gap=Number(field('official-gap'))||0;stopAllPlayback();let epoch=communityEpoch;officialActive=true;let alive=()=>officialActive&&epoch===communityEpoch&&page==='official';try{for(let i=0;i<rows.length&&alive();i++){let a=rows[i];officialStatus('불러오는 중 · '+a.title);let blob=await officialBlob(a);if(!alive())return;officialUrl=URL.createObjectURL(blob);for(let j=0;j<repeat&&alive();j++){while(officialPaused&&alive())await sleep(100);if(!alive())return;officialStatus(a.title+' · '+(i+1)+'/'+rows.length+' · 반복 '+(j+1)+'/'+repeat);let player=new Audio(officialUrl);communityPlayer=player;player.playbackRate=speed;let ok=await new Promise((resolve,reject)=>{officialCancel=resolve;player.onended=()=>resolve(true);player.onerror=()=>reject(Error('음성 파일 재생 실패'));player.play().catch(reject)});officialCancel=null;if(!ok||!alive())return;communityPlayer=null;if(j<repeat-1||i<rows.length-1){for(let t=0;t<gap*10&&alive();){await sleep(100);if(!officialPaused)t++}}}if(officialUrl){URL.revokeObjectURL(officialUrl);officialUrl=null}}if(alive())officialStatus('재생 완료')}catch(e){if(alive()){officialStatus('재생 중단 · '+(e.message||'다시 시도하세요.'));toast('재생 버튼을 다시 눌러 주세요.')}}finally{if(epoch===communityEpoch){if(communityPlayer)communityPlayer.pause();communityPlayer=null;officialClean()}}}
async function officialAction(k,id){if(!['officialstop','officialremove'].includes(k)){await refreshOfficialSetting();if(page!=='official')return;if(!officialEnabled){stopAllPlayback();return officialPage()}}let a=officialRows.find(x=>x.id===id);switch(k){case'officialqueue':return officialPlay(officialRows.filter(x=>field('official-language')==='all'||x.language===field('official-language')));case'officialsingle':if(a)return officialPlay([a]);return;case'officialstop':stopAllPlayback();officialStatus('재생 정지');return;case'officialpause':if(!officialActive)return;officialPaused=!officialPaused;if(communityPlayer){if(officialPaused)communityPlayer.pause();else await communityPlayer.play()}officialStatus(officialPaused?'일시정지':'재생 중');return;case'officialdownload':if(!a)return;{let c=onlineCommunity(),epoch=communityEpoch;let live=must(await c.from('official_audio').select('id').eq('id',id).eq('published',true).single());if(!live)return;let blob=must(await c.storage.from('yw-official-audio').download(a.object_path));if(blob.size>15000000)throw Error('파일 크기 초과');await officialOp('readwrite',s=>s.put({id:a.id,meta:a,blob}));toast('오프라인 저장 완료');if(page==='official'&&epoch===communityEpoch){stopAllPlayback();return officialPage()}}return;case'officialremove':await officialOp('readwrite',s=>s.delete(id));stopAllPlayback();return officialPage()}}

let cmGroup=null,cmReturn='community';
async function rosterPage(g){let epoch=++communityEpoch;cmGroup=g;app.innerHTML=heading('Group','그룹 명단')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),rows=must(await c.rpc('yw_group_roster',{g}));if(page!=='roster'||epoch!==communityEpoch)return;let admin=await adminCheck();if(page!=='roster'||epoch!==communityEpoch)return;app.innerHTML=btn('← 돌아가기','goto:'+cmReturn,'outline')+heading('Group','그룹 명단 및 진척도')+'<p class="muted">학생이 제출한 요약입니다. 미제출 기록은 —로 표시됩니다.</p>'+rows.map(u=>'<section class="card"><b>'+esc(u.display_name||'이름 미등록')+'</b><p>'+esc(u.role)+' · '+(u.completed??'—')+' / 15 완료 · '+(u.attempts??'—')+'회 학습</p><small>'+esc(cmDate(u.reported_at))+'</small>'+(admin?btn(u.role==='leader'?'학생으로 변경':'리더로 지정','cmrole:'+u.user_id,'outline')+btn('그룹에서 제거','cmremove:'+u.user_id,'outline'):'')+'</section>').join('');}catch(e){if(page==='roster'&&epoch===communityEpoch)app.innerHTML=heading('Group','그룹 명단')+esc(e.message)}}
async function submissionsPage(g){let epoch=++communityEpoch;cmGroup=g;app.innerHTML=heading('Recite','그룹 녹음')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),[rows,feedback,lead]=await Promise.all([c.from('yw_submissions').select('*').eq('group_id',g),c.from('yw_feedback').select('*'),c.rpc('yw_is_leader',{g})]).then(rs=>rs.map(must));let recordings=await recOp('readonly',s=>s.getAll());if(page!=='submissions'||epoch!==communityEpoch)return;app.innerHTML=btn('← 공동체','goto:community','outline')+heading('Recite','그룹 녹음 및 피드백')+'<section class="card stack"><p>선택한 녹음만 이 그룹의 담당 리더에게 공유됩니다.</p><select id="submit-recording">'+options(recordings.map(r=>[r.id,r.name]),recordings[0]?.id)+'</select>'+btn('선택한 녹음 제출','cmsubmit','primary')+'</section>'+rows.map(r=>'<section class="card"><b>'+esc(r.reference)+'</b><p>'+esc(cmDate(r.created_at))+' · '+(r.user_id===identity.id?'내 제출':'학생 제출')+'</p>'+btn('듣기','cmsubplay:'+r.id,'outline')+btn('정지','cmstop','outline')+'<p>'+esc(feedback.find(f=>f.submission_id===r.id)?.body||'아직 피드백 없음')+'</p>'+(lead?btn('피드백 작성','cmfeedback:'+r.id,'outline'):'')+(r.user_id===identity.id?btn('제출 취소','cmwithdraw:'+r.id,'outline'):'')+'</section>').join('');}catch(e){if(page==='submissions'&&epoch===communityEpoch)app.innerHTML=heading('Recite','그룹 녹음')+esc(e.message)}}
async function uploadOfficial(blob,itemKey,language,title){let c=onlineCommunity();if(!await adminCheck())throw Error('관리자 권한이 필요합니다.');if(!blob||blob.size===0||blob.size>15000000)throw Error('15MB 이하의 음성 파일을 선택하세요.');if(!title.trim())throw Error('음성 제목을 입력하세요.');let path=identity.id+'/'+crypto.randomUUID();must(await c.storage.from('yw-official-audio').upload(path,blob,{contentType:blob.type||'audio/mpeg',upsert:false}));try{must(await c.from('official_audio').insert({item_key:itemKey,language,title:title.trim(),object_path:path,published:false}))}catch(e){await c.storage.from('yw-official-audio').remove([path]);throw e}toast('공식 음성 초안 등록 완료');if(page==='admin')adminPage()}
async function playCommunity(bucket,path){let c=onlineCommunity();stopAllPlayback();let epoch=communityEpoch;let data=must(await c.storage.from(bucket).createSignedUrl(path,120));if(epoch!==communityEpoch)return;communityPlayer=new Audio(data.signedUrl);await communityPlayer.play();toast('음성 재생 중')}
async function communityAction(k,id){let c=onlineCommunity();
 switch(k){
 case'cmcreate':{let name=field('new-group').trim();if(!name)return toast('그룹 이름을 입력하세요.');must(await c.from('yw_groups').insert({name}));return adminPage()}
 case'cmtoggle':{let g=must(await c.from('yw_groups').select('active').eq('id',id).single());if(!confirm(g.active?'그룹을 종료할까요?':'그룹을 재개할까요?'))return;must(await c.from('yw_groups').update({active:!g.active}).eq('id',id));return adminPage()}
 case'cminvite':{let code=crypto.randomUUID().replace(/-/g,'');must(await c.rpc('yw_set_invite',{g:id,code}));prompt('7일 유효 초대 코드 (기존 코드는 만료됩니다)',code);return}
 case'cmjoin':{must(await c.rpc('yw_join_group',{code:field('group-code').trim().toLowerCase()}));toast('가입 완료');return communityPage()}
 case'cmroster':cmGroup=id;cmReturn=page==='admin'?'admin':'community';return go('roster');
 case'cmrole':{let row=must(await c.from('yw_members').select('role').eq('group_id',cmGroup).eq('user_id',id).single());if(!confirm('그룹 역할을 변경할까요?'))return;must(await c.from('yw_members').update({role:row.role==='leader'?'student':'leader'}).eq('group_id',cmGroup).eq('user_id',id));return rosterPage(cmGroup)}
 case'cmremove':if(confirm('이 회원을 그룹에서 제거할까요?')){must(await c.from('yw_members').delete().eq('group_id',cmGroup).eq('user_id',id));return rosterPage(cmGroup)}return;
 case'cmtitle':{let title=prompt('과 제목');if(title===null)return;must(await c.from('official_curriculum').update({lesson_title:title.trim()}).eq('item_key',id));return adminPage()}
 case'cmprogress':{if(!confirm('기본 15개 항목의 완료 수, 입력 수, 학습 횟수를 담당 리더에게 공유할까요?'))return;let xs=db.items.filter(x=>refs.some((_,i)=>x.id==='yes-'+i)),keys=new Set(xs.map(x=>x.id));must(await c.from('yw_group_progress').upsert({group_id:id,user_id:identity.id,completed:xs.filter(complete).length,entered:xs.filter(x=>x.text.trim()).length,attempts:db.attempts.filter(a=>keys.has(a.item)).length,updated_at:new Date().toISOString()}));return toast('요약 진척도 제출 완료')}
 case'cmupload':return uploadOfficial(document.getElementById('official-file')?.files[0],field('official-item'),field('official-lang'),field('official-title'));
 case'cmrecord':{if(communityRecorder?.state==='recording')return;let key=field('official-item'),lang=field('official-lang'),title=field('official-title');if(!title.trim())return toast('제목을 먼저 입력하세요.');if(!await adminCheck())throw Error('권한 없음');let epoch=communityEpoch;communityStream=await navigator.mediaDevices.getUserMedia({audio:true});if(page!=='admin'||epoch!==communityEpoch){communityStream.getTracks().forEach(t=>t.stop());return}let chunks=[],r=new MediaRecorder(communityStream);communityRecorder=r;r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=()=>{communityStream?.getTracks().forEach(t=>t.stop());communityStream=null;communityRecorder=null;if(page==='admin'&&epoch===communityEpoch)uploadOfficial(new Blob(chunks,{type:r.mimeType||'audio/webm'}),key,lang,title).catch(communityError)};r.start();setTimeout(()=>{if(r.state==='recording')r.stop()},300000);return toast('공식 음성 녹음 중')}
 case'cmrecordstop':if(communityRecorder?.state==='recording')communityRecorder.stop();return;
 case'cmplay':{let a=must(await c.from('official_audio').select('object_path').eq('id',id).single());return playCommunity('yw-official-audio',a.object_path)}
 case'cmstop':return stopAllPlayback();
 case'cmpublish':{let a=must(await c.from('official_audio').select('published').eq('id',id).single());if(!a.published&&!confirm('본문 및 음성 배포에 필요한 권한을 확인했나요? 가입 사용자에게 공개합니다.'))return;must(await c.from('official_audio').update({published:!a.published}).eq('id',id));return adminPage()}
 case'cmdeleteaudio':{if(!confirm('공식 음성을 삭제할까요?'))return;let a=must(await c.from('official_audio').select('object_path').eq('id',id).single());must(await c.from('official_audio').delete().eq('id',id));let removal=await c.storage.from('yw-official-audio').remove([a.object_path]);if(removal.error)toast('목록 삭제 완료, 파일 정리 필요');return adminPage()}
 case'cmsubmissions':cmGroup=id;return go('submissions');
 case'cmsubmit':{let rec=await recOp('readonly',s=>s.get(field('submit-recording')));if(!rec||!rec.blob||rec.blob.size>15000000)return toast('15MB 이하의 녹음을 선택하세요.');if(!confirm('이 녹음만 담당 리더에게 제출할까요?'))return;let g=cmGroup,sid=crypto.randomUUID(),path=identity.id+'/'+g+'/'+sid;must(await c.from('yw_submissions').insert({id:sid,group_id:g,user_id:identity.id,reference:(item(rec.item)?.ref||rec.name).slice(0,200),object_path:path}));try{must(await c.storage.from('yw-submissions').upload(path,rec.blob,{contentType:rec.blob.type||'audio/webm',upsert:false}))}catch(e){await c.from('yw_submissions').delete().eq('id',sid);throw e}toast('녹음 제출 완료');return submissionsPage(g)}
 case'cmsubplay':{let a=must(await c.from('yw_submissions').select('object_path').eq('id',id).single());return playCommunity('yw-submissions',a.object_path)}
 case'cmwithdraw':{if(!confirm('제출을 취소할까요? 기존에 발급된 재생 링크는 최대 2분간 유효할 수 있습니다.'))return;let a=must(await c.from('yw_submissions').select('object_path').eq('id',id).single());must(await c.from('yw_submissions').delete().eq('id',id));let r=await c.storage.from('yw-submissions').remove([a.object_path]);if(r.error)toast('접근 권한 취소 완료, 파일 정리 필요');return submissionsPage(cmGroup)}
 case'cmfeedback':{let body=prompt('학생에게 보낼 피드백 (최대 2000자)');if(!body?.trim())return;must(await c.from('yw_feedback').upsert({submission_id:id,reviewer_id:identity.id,body:body.trim().slice(0,2000),updated_at:new Date().toISOString()}));return submissionsPage(cmGroup)}
 }
}


let favFilter='all',selectedStudy=new Set(),studyScope='all',bulkDraft=[],bulkPreview=null;
function wrongItems(){return filled().filter(x=>{let a=db.attempts.slice().reverse().find(y=>y.item===x.id&&Number.isFinite(y.score)&&!y.hint&&y.version===x.version);return a&&a.score<90})}
function favoritesPage(){let xs=favFilter==='fav'?db.items.filter(x=>x.favorite):db.items;app.innerHTML=btn('← 암송 훈련','goto:study','outline')+heading('Library','나의 즐겨찾기')+'<p>별표를 눌러 자주 암송할 말씀을 모으세요. 본문을 입력한 말씀만 훈련할 수 있습니다.</p><div class="row">'+btn('전체 말씀','favfilter:all','outline grow')+btn('즐겨찾기 ('+db.items.filter(x=>x.favorite).length+')','favfilter:fav','outline grow')+'</div>'+xs.map(x=>'<section class="card"><div class="row between"><div><small>'+esc(plan(x.plan)?.title||'')+' · '+(x.text.trim()?'본문 등록':'본문 입력 대기')+'</small><h3>'+esc(x.ref)+'</h3></div>'+btn(x.favorite?'★ 저장됨':'☆ 추가','fav:'+x.id,'outline','aria-pressed="'+Boolean(x.favorite)+'"')+'</div></section>').join('')+(xs.length?'':'<section class="card">즐겨찾기가 없습니다. 전체 말씀에서 별표를 눌러 주세요.</section>')+btn('즐겨찾기 '+filled().filter(x=>x.favorite).length+'개 암송','favtrain','primary full')}
function studyScopeUI(){let e=$('#scope-guide');if(!e)return;let v=$('#scope').value;e.innerHTML='<p>학습 가능한 말씀 '+scoped(v).length+'개</p>'+(v==='fav'?'<p>플랜의 ☆ 또는 즐겨찾기 관리에서 추가할 수 있습니다.</p>':v==='wrong'?'<p>최근 힌트 없는 채점에서 90점 미만인 말씀입니다.</p>':v==='selected'?'<p>암송할 말씀을 직접 선택하세요.</p>'+filled().map(x=>'<label style="display:block"><input type="checkbox" data-study-id="'+esc(x.id)+'" '+(selectedStudy.has(x.id)?'checked':'')+'> '+esc(x.ref)+'</label>').join(''):'');e.querySelectorAll('[data-study-id]').forEach(el=>el.onchange=()=>{if(el.checked)selectedStudy.add(el.dataset.studyId);else selectedStudy.delete(el.dataset.studyId);studyScopeUI()})}
function startBulk(){bulkDraft=db.items.filter(x=>x.plan===currentPlan&&!x.text.trim()).map(x=>({id:x.id,ref:x.ref,text:'',lang:x.lang||'ko-KR',translation:x.translation||'개역개정'}));if(!bulkDraft.length)bulkDraft=[{ref:'',text:'',lang:'ko-KR',translation:'개역개정'}];bulkPreview=null;go('bulkpage')}
function captureBulk(){document.querySelectorAll('[data-bulk-index]').forEach(el=>{let i=Number(el.dataset.bulkIndex);if(bulkDraft[i])bulkDraft[i][el.dataset.field]=el.value})}
function bulkPage(){if(!plan(currentPlan))return go('plans');app.innerHTML=btn('← 플랜','goto:detail','outline')+heading('Library','말씀 일괄 등록')+'<section class="card"><h3>등록 방법</h3><p>성경 주소와 본문을 별도 입력란에 붙여넣으세요. 본문 줄바꿈은 유지됩니다. 빈 항목은 등록하지 않습니다.</p><details><summary>정리된 자료 한꺼번에 붙여넣기</summary><p>첫 줄은 성경 주소, 다음 줄부터 본문입니다. 구절 사이는 빈 줄로 구분하세요. 또는 주소 | 본문 형식으로 한 줄씩 입력하세요.</p><pre>로마서 5:8\n[본문 붙여넣기]\n\n여호수아 1:8\n[본문 붙여넣기]</pre><textarea id="bulk-paste" rows="6" placeholder="정리된 자료 붙여넣기"></textarea>'+btn('입력란으로 변환','bulkparse','outline full')+'</details></section>'+bulkDraft.map((r,i)=>'<section class="card stack"><div class="row between"><b>말씀 '+(i+1)+'</b>'+btn('제거','bulkremove:'+i,'outline')+'</div><label>성경 주소</label><input data-bulk-index="'+i+'" data-field="ref" value="'+esc(r.ref)+'" '+(r.id?'readonly':'')+' placeholder="예: 로마서 5:8"><label>번역본</label><select data-bulk-index="'+i+'" data-field="translation">'+options([['개역개정','개역개정'],['ESV','ESV'],['기타','기타']],r.translation)+'</select><label>성경 본문</label><textarea rows="4" data-bulk-index="'+i+'" data-field="text" placeholder="여기에 성경 본문을 붙여넣으세요">'+esc(r.text)+'</textarea></section>').join('')+btn('+ 말씀 입력란 추가','bulkadd','outline full')+btn('등록 전 미리보기','bulkpreview','primary full')}
function refKey(s){return s.normalize('NFKC').replace(/[–—−]/g,'-').replace(/\s+/g,'').toLowerCase()}
function previewBulk(){captureBulk();let rows=bulkDraft.filter(x=>x.text.trim());if(!rows.length)return toast('본문을 하나 이상 입력하세요.');if(rows.some(x=>!x.ref.trim()))return toast('본문이 있는 항목에 주소를 입력하세요.');let seen=new Set();bulkPreview=rows.map(r=>{let lang=r.translation==='ESV'?'en-US':r.translation==='개역개정'?'ko-KR':r.lang||'ko-KR';let existing=r.id?item(r.id):db.items.find(x=>x.plan===currentPlan&&refKey(x.ref)===refKey(r.ref)&&x.lang===lang);let key=existing?.id||lang+':'+refKey(r.ref);let dup=seen.has(key);seen.add(key);return {...r,lang,existing:existing?.id,duplicate:dup,replace:false}});app.innerHTML=heading('Review','일괄 등록 미리보기')+'<p>중복 구절은 기본적으로 기존 본문을 유지합니다. 교체하려면 직접 선택하세요.</p>'+bulkPreview.map((r,i)=>'<section class="card"><b>'+esc(r.ref)+'</b><small>'+esc(r.translation)+'</small><p style="white-space:pre-wrap">'+esc(r.text)+'</p>'+(r.duplicate?'<p>같은 입력 내 중복 · 건너뜀</p>':item(r.existing)?.text.trim()?'<label><input type="checkbox" data-bulk-replace="'+i+'"> 기존 본문 교체</label>':'<p>신규 또는 빈 본문 등록</p>')+'</section>').join('')+btn('← 입력 수정','bulkback','outline full')+btn('확인 및 저장','bulkcommit','primary full')}
function commitBulk(){if(!bulkPreview)return;document.querySelectorAll('[data-bulk-replace]').forEach(e=>bulkPreview[Number(e.dataset.bulkReplace)].replace=e.checked);let n=0;for(let r of bulkPreview){if(r.duplicate)continue;let old=r.existing?item(r.existing):db.items.find(x=>x.plan===currentPlan&&refKey(x.ref)===refKey(r.ref)&&x.lang===r.lang);if(old){if(old.text.trim()&&!r.replace)continue;if(old.text!==r.text||old.translation!==r.translation||old.lang!==r.lang){old.revisions=[...(old.revisions||[]),{text:old.text,ref:old.ref,version:old.version,time:Date.now()}];old.version++;delete db.reviews[old.id]}Object.assign(old,{text:r.text,translation:r.translation,lang:r.lang})}else db.items.push({id:uid(),plan:currentPlan,ref:r.ref.trim(),text:r.text,translation:r.translation,lang:r.lang,version:1,notes:'',favorite:false});n++}save();bulkPreview=null;bulkDraft=[];go('detail');toast(n+'개 말씀 등록 완료')}
function parseBulk(){let raw=$('#bulk-paste')?.value||'';captureBulk();if(!raw.trim())return toast('자료를 붙여넣으세요.');let rows;if(raw.trim().split(/\r?\n/).filter(l=>l.trim()).every(l=>l.includes('|'))){rows=raw.trim().split(/\r?\n/).filter(l=>l.trim()).map(l=>{let p=l.indexOf('|');return {ref:l.slice(0,p).trim(),text:l.slice(p+1).trim()}})}else rows=raw.trim().split(/\r?\n\s*\r?\n/).map(b=>{let lines=b.split(/\r?\n/);return {ref:lines.shift().trim(),text:lines.join('\n').trim()}});if(rows.some(x=>!x.ref||!x.text))return toast('주소와 본문을 확인하고 구절 사이에 빈 줄을 넣어 주세요.');for(let r of rows){let existing=bulkDraft.find(x=>refKey(x.ref)===refKey(r.ref)&&!x.text.trim());if(existing)existing.text=r.text;else bulkDraft.push({...r,lang:'ko-KR',translation:'개역개정'})}bulkPage()}


let officialEnabled=false,officialSettingsReady=false,historyRange='week',historyLimit=30;
async function refreshOfficialSetting(){if(!window.YES_CLIENT||!navigator.onLine)return;try{let r=await window.YES_CLIENT.from('yw_service_settings').select('official_audio_enabled').eq('singleton',true).single();if(r.error)throw r.error;officialEnabled=r.data.official_audio_enabled===true;officialSettingsReady=true;localStorage.setItem(storageKey+':official-enabled',String(officialEnabled))}catch{officialEnabled=false;officialSettingsReady=false}}
try{officialEnabled=localStorage.getItem(storageKey+':official-enabled')==='true'}catch{}
function serviceSettingsPanel(){return '<section class="card stack"><h3>서비스 설정</h3><p>공식 음성 '+(officialEnabled?'활성화':'비활성화')+'</p><p class="muted">비활성화하면 일반 사용자의 새 음성 접근이 차단됩니다. 이미 기기에 저장된 파일은 오프라인에서 즉시 회수할 수 없습니다. 기본 자동 읽기와 개인 녹음은 유지됩니다.</p>'+btn(officialEnabled?'공식 음성 비활성화':'공식 음성 활성화','officialsetting','primary full',officialSettingsReady?'':'disabled')+(officialSettingsReady?'':'<small>관리자 서비스 설정 SQL 적용 필요</small>')+'</section>'}
async function toggleOfficialSetting(){let c=onlineCommunity();if(!await adminCheck()||!officialSettingsReady)return toast('관리자 설정을 확인하세요.');let next=!officialEnabled;if(!confirm(next?'공식 음성 기능을 활성화할까요?':'공식 음성 기능을 비활성화할까요?'))return;must(await c.from('yw_service_settings').update({official_audio_enabled:next}).eq('singleton',true).select('singleton').single());await refreshOfficialSetting();return adminPage()}
function historyRows(){let now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(historyRange==='week')start.setDate(start.getDate()-6);if(historyRange==='month')start.setDate(start.getDate()-29);return db.attempts.filter(a=>historyRange==='all'||a.time>=start.getTime()).slice().sort((a,b)=>b.time-a.time)}
function historyRow(a){let x=item(a.item);return '<div class="history-row"><div><strong>'+esc(x?.ref||'삭제된 말씀')+'</strong><small>'+esc(cmDate(a.time))+' · '+esc(modes.find(m=>m[0]===a.mode)?.[1]||'암송')+'</small></div><strong class="history-score">'+esc(a.score==null?'자기 평가':a.score+'점')+'</strong></div>'}
function historySummary(){return '<h2>최근 학습 기록</h2><section class="card history-list">'+(db.attempts.length?db.attempts.slice(-5).reverse().map(historyRow).join(''):'<p class="muted">아직 학습 기록이 없습니다.</p>')+btn('전체 학습 History 보기','goto:history','outline full')+'</section>'}
function historyPage(){let rows=historyRows(),scores=rows.filter(a=>Number.isFinite(a.score));let filters=[['today','오늘'],['week','7일'],['month','30일'],['all','전체']];let chart='';if(historyRange!=='all'){let n=historyRange==='today'?1:historyRange==='week'?7:30;let ds=Array.from({length:n},(_,i)=>{let d=new Date();d.setDate(d.getDate()-n+1+i);return {d:day(d),count:rows.filter(a=>day(a.time)===day(d)).length}});let max=Math.max(1,...ds.map(d=>d.count));chart='<section class="card"><h3>학습 횟수</h3><div class="history-chart">'+ds.map(d=>'<div title="'+esc(d.d+' · '+d.count+'회')+'"><i style="height:'+Math.max(2,d.count/max*100)+'%"></i></div>').join('')+'</div><div class="row between"><small>'+ds[0].d+'</small><small>'+ds[ds.length-1].d+'</small></div></section>'}app.innerHTML=btn('← MY','goto:my','outline')+heading('History','학습 기록')+'<div class="history-filters">'+filters.map(([id,t])=>btn(t,'historyrange:'+id,historyRange===id?'primary':'outline')).join('')+'</div><div class="grid"><div class="card"><small>학습 횟수</small><div class="metric">'+rows.length+'회</div></div><div class="card"><small>평균 채점</small><div class="metric">'+(scores.length?Math.round(scores.reduce((sum,a)=>sum+a.score,0)/scores.length)+'점':'—')+'</div></div></div>'+chart+'<h2>상세 기록</h2><section class="card history-list">'+(rows.length?rows.slice(0,historyLimit).map(historyRow).join(''):'<p class="muted">해당 기간의 학습 기록이 없습니다.</p>')+(rows.length>historyLimit?btn('더 보기','historymore','outline full'):'')+'</section>'}

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go)go(b.dataset.go);if(b.dataset.act)Promise.resolve(action(b.dataset.act)).catch(err=>{console.error(err);toast('작업 중 오류가 발생했습니다.')})});history.replaceState({yesPage:page},'');window.addEventListener('popstate',e=>go(e.state?.yesPage||'home',true));window.addEventListener('pagehide',stopAllPlayback);document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO'){stopAudio();document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})}},true);render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
